<p>{note.body}</p>

// Unsafe: the browser runs any HTML inside
<div dangerouslySetInnerHTML={{ __html: note.body }} />

// If you must render HTML, sanitize it first
<div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(html) }} />

// Unsafe: input is glued into the command
db.query(`select * from notes where title ilike '%${q}%'`);

// Safe: $1 is a placeholder, q travels separately
db.query('select * from notes where title ilike $1', [`%${q}%`]);

const { id } = await params; // from /api/notes/[id]
const supabase = await createClient(); // user's token, RLS on
const { data: { user } } = await supabase.auth.getUser();
if (!user) return new Response('Log in first', { status: 401 });

const { data: note } = await supabase
  .from('notes')
  .select('*')
  .eq('id', id)
  .eq('user_id', user.id) // ownership, belt and braces
  .maybeSingle();

if (!note) return new Response('Not found', { status: 404 });
return Response.json(note);
